    title: 'Founder & CEO',
    organization: { name: 'Lumina Commerce', website_url: 'luminaecommerce.co' },
    headline: '8-figure multi-brand Shopify ecosystem',
    pain_point: 'Disconnected inventory sync between Shopify, 3PL, and QuickBooks'
  }
];

const rawLeads = apolloData.length > 0 ? apolloData : sampleLeads;

return rawLeads.map(lead => ({
  json: {
    first_name: lead.first_name,
    last_name: lead.last_name,
    full_name: `${lead.first_name} ${lead.last_name}`,
    email: lead.email,
    title: lead.title,
    company_name: lead.organization ? lead.organization.name : 'your company',
    domain: lead.organization ? lead.organization.website_url : '',
    pain_point: lead.pain_point || 'Operational manual bottlenecks in data and workflow routing'
  }
}));

messageValues.message:
=You are an elite B2B Solutions Architect at Zenthra Systems (an engineering consultancy specializing in enterprise n8n workflow systems, autonomous AI agents, and data engineering pipelines).

Your task is to write a highly technical, non-salesy, hyper-personalized 3-sentence outreach email to a prospective client.

Prospect Details:
- Name: {{ $json.first_name }} {{ $json.last_name }}
- Title: {{ $json.title }}
- Company: {{ $json.company_name }}
- Known Operational Pain Point: {{ $json.pain_point }}

Strict Rules:
1. Tone: Consultative, senior peer-to-peer, zero fluff, zero generic compliments like 'hope this finds you well'.
2. Sentence 1: Acknowledge their exact operational bottleneck.
3. Sentence 2: Mention how Zenthra Systems solved this exact problem using an automated n8n pipeline or AI agent architecture with specific metrics (e.g. reducing triage latency from 45 min to 30 sec).
4. Sentence 3: Low-friction CTA asking if they are open to reviewing an asynchronous 2-minute architectural blueprint.

Return clean JSON in the format:
{
  "subject": "n8n workflow for {{ $json.company_name }}'s operations",
  "body": "[email body]"
}

parameters.jsCode:
let parsed;
try {
  const raw = $json.message.content.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(raw);
} catch(e) {
  parsed = {
    subject: `Technical architecture inquiry for ${$('Normalize & Filter Verified Leads').item.json.company_name}`,
    body: `Hi ${$('Normalize & Filter Verified Leads').item.json.first_name},\n\nNoticed your team is scaling operations at ${$('Normalize & Filter Verified Leads').item.json.company_name}. We recently built an automated n8n pipeline solving ${$('Normalize & Filter Verified Leads').item.json.pain_point}, cutting latency by 90% without adding headcount.\n\nWould you be open to an asynchronous 2-minute blueprint of how we wired this up?\n\nBest,\nZenthra Systems Engineering Team\nconnect.zenthra@gmail.com`
  };
}

return {
  json: {
    to_email: $('Normalize & Filter Verified Leads').item.json.email,
    to_name: $('Normalize & Filter Verified Leads').item.json.full_name,
    company: $('Normalize & Filter Verified Leads').item.json.company_name,
    subject: parsed.subject,
    body: parsed.body
  }
};

return {
  json: {
    event: 'OUTBOUND_DISPATCH_CONFIRMED',
    recipient: $json.to_name,
    email: $json.to_email,
    company: $json.company,
    subject: $json.subject,
    status: 'DISPATCHED_TO_LEAD',
    timestamp: new Date().toISOString()
  }
};
